SetColumns(0);SetQuitOnError(true);SetNthreads(1);SetMemoryLimit(5*10^9);Alarm(240);tt:=Cputime();AttachSpec("work/deg10/shared/mdmagma/v2/mdmagma.spec");load "work/deg10/continuation_20261031b/C60/inputs/a3_model.m";
root:="work/deg10/continuation_20261031b/C60/";G,_,phi:=ClassGroup(A3K:ReductionDivisor:=Divisor(A3c0),Proof:=true);assert Invariants(G)eq[2,2,2,2,2,2,102,10608,0];hs:=[phi(o-Degree(o)*Divisor(A3c0)):o in A3orbits];H:=sub<G|hs>;assert #H eq 256;
queue:=[G!0];seen:={G!0};pos:=1;while pos le #queue do for h in hs do aa:=queue[pos]+h;if aa notin seen then Include(~seen,aa);Append(~queue,aa);end if;end for;pos+:=1;end while;assert #queue eq 256;
eff:=AssociativeArray();for d in[0..10]do eff[d]:=AssociativeArray();end for;eff[0][G!0]:=[0:i in hs];for j in[1..#hs]do w:=Degree(A3orbits[j]);for d in[w..10]do for aa in Keys(eff[d-w])do bb:=aa+hs[j];v:=eff[d-w][aa];v[j]+:=1;if not IsDefined(eff[d],bb)then eff[d][bb]:=v;end if;end for;end for;end for;assert #Keys(eff[10])eq 256;
baseorbs:=[FunctionFieldDivisor(o):o in A3baseorbits];nu:=[Valuation(A3disc15,Support(D)[1]):D in baseorbs];assert &and[IsOdd(v):v in nu];cases:=[* *];mixed:=[* *];pullback:=[* *];fixed:=0;
for ci in[1..256]do cl:=queue[ci];v:=eff[10][cl];D:=&+[v[j]*A3orbits[j]:j in[1..#v]];assert Degree(D)eq 10;Bp:=&+[(v[j] div 2)*baseorbs[j]:j in[1..#v]];Bn:=&+[Floor((v[j]+nu[j])/2)*baseorbs[j]:j in[1..#v]];hp:=Dimension(Bp);hn:=Dimension(Bn);bb:=Basis(D:Reduction:=false,Simplification:="None");assert #bb eq hp+hn;par:=&+[(v[j]mod 2)*Degree(A3orbits[j]):j in[1..#v]];
 if hp gt 0 and hn gt 0 then typ:=2;Append(~mixed,[*ci,v,hp+hn,hp,hn*]);elif hp gt 0 and par eq 0 then typ:=1;Append(~pullback,[*ci,v,hp,hn*]);else typ:=0;fixed+:=1;end if;
 Append(~cases,[*ci,Eltseq(cl),v,Dimension(D),hp,hn,typ,Degree(Bp),Degree(Bn),par*]);if ci mod 32 eq 0 then print "D31B_C60_D10_SERIES_PROGRESS",ci,#mixed,#pullback,fixed,Cputime(tt);end if;
end for;
Write(root cat "degree10_series.m",Sprint([*[Eltseq(v):v in Rows(RelationMatrix(G))],A3signatures,[Degree(o):o in A3orbits],[Eltseq(h):h in hs],nu,cases,mixed,pullback*]):Overwrite:=true);print "D31B_C60_D10_SERIES_COMPLETE",#cases,#mixed,#pullback,fixed,[[v[4],v[5]]:v in mixed],Cputime(tt);quit;
